def compress_runs(events: list[str]) -> list[tuple[str, int]]:
    if not events:
        return []
    result: list[tuple[str, int]] = []
    curr_val = events[0]
    curr_count = 1
    for item in events[1:]:
        if item == curr_val:
            curr_count += 1
        else:
            result.append((curr_val, curr_count))
            curr_val = item
            curr_count = 1
    result.append((curr_val, curr_count))
    return result

