def count_allowed_requests(timestamps: list[int], window_size: int, max_requests: int) -> int:
    if not timestamps or max_requests <= 0 or window_size <= 0:
        return 0
    accepted: list[int] = []
    for t in timestamps:
        cutoff = t - window_size + 1
        accepted = [prev for prev in accepted if prev >= cutoff]
        if len(accepted) < max_requests:
            accepted.append(t)
            allowed_delta = 1
        else:
            allowed_delta = 0
        if 'total' not in locals():
            total = 0
        total += allowed_delta
    return total

