verified_repairs.allocate_fifo_inventory:
def allocate_fifo_inventory(batches: list[int], order_qty: int) -> list[int]:
    if order_qty <= 0 or not batches:
        return list(batches)
    if sum(batches) < order_qty:
        return list(batches)
    remaining_order = order_qty
    updated: list[int] = []
    for qty in batches:
        if remaining_order <= 0:
            updated.append(qty)
        elif qty >= remaining_order:
            updated.append(qty - remaining_order)
            remaining_order = 0
        else:
            updated.append(0)
            remaining_order -= qty
    return updated

